"""JSON, Markdown, and self-contained HTML renderers for a ``Report``.

All three follow the same structure. Citations like ``[F-0042]`` become links to the
finding in the appendix; the finding lists its nodes and edges, each linked to the file and
line at the commit when the report knows the repository URL.
"""

from __future__ import annotations

import html
import json
import re
from typing import Any

from lantern_report.dpia import Report, Section, Table
from lantern_report.narrative import CITATION

DISCLAIMER = (
    "Generated by Lantern from the code at this commit. It describes what the code does; it "
    "is not legal advice, and sections marked for the controller need human answers."
)


def anchor(finding_id: str) -> str:
    return finding_id.lower()


# --------------------------------------------------------------------------- JSON


def render_json(report: Report) -> str:
    return json.dumps(report.to_dict(), indent=2, sort_keys=True, default=str)


# --------------------------------------------------------------------------- Markdown


def _md_cite(text: str) -> str:
    return CITATION.sub(lambda m: f"[[{m.group(1)}]](#{anchor(m.group(1))})", text)


def _md_cell(text: str) -> str:
    return _md_cite(str(text).replace("|", "\\|").replace("\n", " ")) or " "


def _md_link(text: str, url: str | None) -> str:
    return f"[{text}]({url})" if url else f"`{text}`"


def _md_table(table: Table) -> list[str]:
    if not table.rows:
        return [f"_{table.caption or 'Table'}: nothing to list._", ""]
    out = [f"**{table.caption}**", ""] if table.caption else []
    out.append("| " + " | ".join(table.columns) + " |")
    out.append("|" + "---|" * len(table.columns))
    out += ["| " + " | ".join(_md_cell(c) for c in row) + " |" for row in table.rows]
    return [*out, ""]


def _md_section(section: Section, level: int) -> list[str]:
    out = [f"{'#' * level} {section.title}", ""]
    if section.basis:
        out += [f"_Basis: {section.basis}_", ""]
    if section.intro:
        out += [section.intro, ""]
    if section.narrative and section.narrative.sentences:
        out += [_md_cite(" ".join(section.narrative.sentences)), ""]
    for table in section.tables:
        out += _md_table(table)
    for item in section.items:
        out += _md_unresolved(item, level + 1)
    for note in section.notes:
        out += [f"> {note}", ""]
    for child in section.children:
        out += _md_section(child, level + 1)
    return out


def _md_unresolved(item: dict[str, Any], level: int) -> list[str]:
    title = f"[{item['finding']}] {item['title']}" if item["finding"] else item["title"]
    out = [f"{'#' * level} {_md_cite(title)}", ""]
    flow = item["flow"]
    if flow.get("sources"):
        out.append(f"- **Sources:** {'; '.join(f'`{s}`' for s in flow['sources'])}")
    if flow.get("sink"):
        out.append(f"- **Sink:** {_md_link(flow['sink'], flow.get('sink_url'))}")
    if flow.get("destination"):
        out.append(f"- **Destination:** {flow['destination']}")
    for step in item["evidence"]:
        where = f"{step.get('file')}:{step.get('line')}"
        out.append(
            f"- **Unresolved step:** {_md_link(where, step.get('url'))} `{step.get('text', '')}`"
            f" ({step.get('note', '')})"
        )
    for d in item["decisions"]:
        out.append(
            f"- **Low-confidence decision:** {d['question']} = `{d['answer']}` "
            f"(p = {d['probability']:.2f})"
        )
    out += ["", "**Reviewer must check:**", ""]
    out += [f"{n}. {text}" for n, text in enumerate(item["instructions"], 1)]
    return [*out, ""]


def _md_finding(f: dict[str, Any]) -> list[str]:
    out = [
        f'### <a id="{anchor(f["id"])}"></a>{f["id"]}: {f["title"]}',
        "",
        f"- **Severity:** {f['severity']} ({', '.join(f['severity_modifiers']) or 'base'}); "
        f"**status:** {f['status']}; **likelihood:** {f['likelihood']}",
        f"- **Data:** {', '.join(f['data_categories']) or '-'}; "
        f"**destination class:** {f['destination_class'] or '-'}",
        f"- **Anchor:** {_md_link(f['anchor_id'], f.get('anchor_url'))}",
    ]
    if f.get("verification"):
        v = f["verification"]
        out.append(f"- **Dynamic verification:** {v.get('status')} ({v.get('reason')})")
    out.append(f"- **Statutes:** {', '.join(f['statute_refs']) or '-'}")
    out.append(f"- **Measure:** {f['measure']}")
    out += ["", "Nodes:", ""]
    for n in f["nodes"]:
        loc = f"{n['file']}:{n['line_start']}"
        out.append(f"- `{n['id']}` {n['kind']} `{n['symbol']}` at {_md_link(loc, n['url'])}")
    if f["edges"]:
        out += ["", "Edges:", ""]
        for e in f["edges"]:
            out.append(f"- `{e['id']}` {e['from']} → {e['to']}")
            for s in e["steps"]:
                loc = f"{s['file']}:{s['line']}"
                flag = " **unresolved**" if s.get("unresolved") else ""
                out.append(f"  - {_md_link(loc, s.get('url'))} {s['kind']}{flag}")
    if f["decisions"]:
        out += ["", "Decisions:", ""]
        for d in f["decisions"]:
            out.append(
                f"- `{d['id']}` {d['target_id']} {d['question']} = `{d['answer']}` "
                f"(p = {d['probability']:.2f}, {d['provider']})"
            )
    return [*out, ""]


def render_markdown(report: Report) -> str:
    run = report.run
    s = report.summary
    out = [
        f"# Data protection impact assessment: {run.repo}",
        "",
        f"Commit `{run.commit}` · run `{run.run_id or '-'}` · generated {run.generated_at} · "
        f"decision provider `{s['provider'] or '-'}` ({s['provider_version'] or '-'}) · question "
        f"set {s['question_set_version'] or '-'} · threshold {s['threshold']} · narrative: "
        f"{', '.join(s.get('narrative', [])) or 'template'}",
        "",
        f"> {DISCLAIMER}",
        "",
        f"**{s['findings']} findings**: "
        + ", ".join(f"{v} {k}" for k, v in sorted(s["by_severity"].items()))
        + f"; {s['unresolved']} unresolved.",
        "",
    ]
    for section in report.sections:
        out += _md_section(section, 2)
    out += ["## Appendix A. Findings", ""]
    for f in report.findings:
        out += _md_finding(f)
    out += ["## Appendix B. Statute references", ""]
    for ref in report.statutes.values():
        verify = " (re-check before relying on it)" if ref.get("verify") else ""
        note = f" {ref['note']}" if ref.get("note") else ""
        out.append(f"- **{ref['id']}**: {ref['citation']}, {ref['title']}.{note}{verify}")
    return "\n".join(out).rstrip() + "\n"


