def _h(text: Any) -> str:
    return html.escape(str(text), quote=True)


def _html_cite(text: str) -> str:
    escaped = _h(text)
    return CITATION.sub(
        lambda m: f'<a class="cite" href="#{anchor(m.group(1))}">[{m.group(1)}]</a>', escaped
    )


def _html_link(text: str, url: str | None) -> str:
    return f'<a href="{_h(url)}">{_h(text)}</a>' if url else f"<code>{_h(text)}</code>"


def _html_table(table: Table) -> str:
    if not table.rows:
        return f'<p class="meta">{_h(table.caption or "Table")}: nothing to list.</p>'
    head = "".join(f"<th>{_h(c)}</th>" for c in table.columns)
    body = "".join(
        "<tr>" + "".join(f"<td>{_html_cite(str(c))}</td>" for c in row) + "</tr>"
        for row in table.rows
    )
    caption = f"<caption>{_h(table.caption)}</caption>" if table.caption else ""
    return (
        f'<div class="scroll"><table>{caption}<thead><tr>{head}</tr></thead>'
        f"<tbody>{body}</tbody></table></div>"
    )


def _html_unresolved(item: dict[str, Any]) -> str:
    title = f"[{item['finding']}] {item['title']}" if item["finding"] else item["title"]
    flow = item["flow"]
    parts = [f"<h4>{_html_cite(title)}</h4><ul>"]
    if flow.get("sources"):
        parts.append(
            "<li><b>Sources:</b> "
            + "; ".join(f"<code>{_h(s)}</code>" for s in flow["sources"])
            + "</li>"
        )
    if flow.get("sink"):
        parts.append(f"<li><b>Sink:</b> {_html_link(flow['sink'], flow.get('sink_url'))}</li>")
    if flow.get("destination"):
        parts.append(f"<li><b>Destination:</b> {_h(flow['destination'])}</li>")
    for step in item["evidence"]:
        where = f"{step.get('file')}:{step.get('line')}"
        parts.append(
            f"<li><b>Unresolved step:</b> {_html_link(where, step.get('url'))} "
            f"<code>{_h(step.get('text', ''))}</code> ({_h(step.get('note', ''))})</li>"
        )
    for d in item["decisions"]:
        parts.append(
            f"<li><b>Low-confidence decision:</b> {_h(d['question'])} = "
            f"<code>{_h(d['answer'])}</code> "
            f"(p = {d['probability']:.2f})</li>"
        )
    parts.append('</ul><p><b>Reviewer must check:</b></p><ol class="instr">')
    parts += [f"<li>{_html_cite(i)}</li>" for i in item["instructions"]]
    parts.append("</ol>")
    return "".join(parts)


def _html_section(section: Section, level: int) -> str:
    tag = f"h{min(level, 6)}"
    parts = [f'<section id="sec-{_h(section.id)}"><{tag}>{_h(section.title)}</{tag}>']
    if section.basis:
        parts.append(f'<p class="basis">Basis: {_h(section.basis)}</p>')
    if section.intro:
        parts.append(f"<p>{_h(section.intro)}</p>")
    if section.narrative and section.narrative.sentences:
        parts.append(
            f'<p class="narrative">{_html_cite(" ".join(section.narrative.sentences))}</p>'
        )
    parts += [_html_table(t) for t in section.tables]
    parts += [_html_unresolved(i) for i in section.items]
    parts += [f'<p class="note">{_h(n)}</p>' for n in section.notes]
    parts += [_html_section(c, level + 1) for c in section.children]
    parts.append("</section>")
    return "".join(parts)


def _html_finding(f: dict[str, Any]) -> str:
    rows = [
        ("Severity", f"{f['severity']} ({', '.join(f['severity_modifiers']) or 'base'})"),
        ("Status", f["status"]),
        ("Likelihood", f["likelihood"]),
        ("Data categories", ", ".join(f["data_categories"]) or "-"),
        ("Destination class", f["destination_class"] or "-"),
        ("Dynamic verification", (f.get("verification") or {}).get("status", "not run")),
        ("Statutes", ", ".join(f["statute_refs"]) or "-"),
        ("Measure", f["measure"]),
    ]
    meta = "".join(f"<tr><th>{_h(k)}</th><td>{_h(v)}</td></tr>" for k, v in rows)
    nodes = "".join(
        f"<li><code>{_h(n['id'])}</code> {_h(n['kind'])} <code>{_h(n['symbol'])}</code> at "
        f"{_html_link(f'{n["file"]}:{n["line_start"]}', n['url'])}"
        + (f"<pre>{_h(n['snippet'])}</pre>" if n.get("snippet") else "")
        + "</li>"
        for n in f["nodes"]
    )
    edges = ""
    for e in f["edges"]:
        items = []
        for st in e["steps"]:
            flag = f" <b>unresolved</b>: {_h(st.get('note', ''))}" if st.get("unresolved") else ""
            where = _html_link(f"{st['file']}:{st['line']}", st.get("url"))
            items.append(f"<li>{where} {_h(st['kind'])} <code>{_h(st['text'])}</code>{flag}</li>")
        steps = "".join(items)
        edges += (
            f"<li><code>{_h(e['id'])}</code> {_h(e['from'])} → {_h(e['to'])}<ol>{steps}</ol></li>"
        )
    decisions = "".join(
        f"<tr><td><code>{_h(d['id'])}</code></td><td>{_h(d['target_id'])}</td><td>{_h(d['question'])}</td>"
        f"<td>{_h(d['answer'])}</td><td>{d['probability']:.2f}</td><td>{_h(d['provider'])}</td></tr>"
        for d in f["decisions"]
    )
    decision_table = (
        "<table><thead><tr><th>Decision</th><th>Target</th><th>Question</th><th>Answer</th>"
        f"<th>p</th><th>Provider</th></tr></thead><tbody>{decisions}</tbody></table>"
        if decisions
        else ""
    )
    return (
        f'<details id="{anchor(f["id"])}"><summary><span class="sev sev-{_h(f["severity"])}">'
        f"{_h(f['severity'])}</span> {_h(f['id'])}: {_h(f['title'])}</summary>"
        f'<div class="scroll"><table>{meta}</table></div>'
        f"<h4>Nodes</h4><ul>{nodes}</ul>"
        + (f"<h4>Edges</h4><ul>{edges}</ul>" if edges else "")
        + (
            f'<h4>Decisions</h4><div class="scroll">{decision_table}</div>'
            if decision_table
            else ""
        )
        + "</details>"
    )


def render_html(report: Report) -> str:
    run = report.run
    s = report.summary
    counts = ", ".join(f"{v} {k}" for k, v in sorted(s["by_severity"].items()))
    body = [
        f"<h1>Data protection impact assessment: {_h(run.repo)}</h1>",
        f'<p class="meta">Commit <code>{_h(run.commit)}</code> · run '
        f"<code>{_h(run.run_id or '-')}</code> "
        f"· generated {_h(run.generated_at)} · decision provider "
        f"<code>{_h(s['provider'] or '-')}</code> "
        f"· question set {_h(s['question_set_version'] or '-')} · threshold {_h(s['threshold'])} "
        f"· narrative: {_h(', '.join(s.get('narrative', [])) or 'template')}</p>",
        f'<p class="disclaimer">{_h(DISCLAIMER)}</p>',
        f"<p><b>{s['findings']} findings</b>: {_h(counts)}; {s['unresolved']} unresolved.</p>",
    ]
    body += [_html_section(sec, 2) for sec in report.sections]
    body.append('<section id="sec-appendix-findings"><h2>Appendix A. Findings</h2>')
    body += [_html_finding(f) for f in report.findings]
    body.append(
        '</section><section id="sec-appendix-statutes"><h2>Appendix B. Statute references</h2><ul>'
    )
    for ref in report.statutes.values():
        verify = " (re-check before relying on it)" if ref.get("verify") else ""
        note = f" {ref['note']}" if ref.get("note") else ""
        body.append(
            f"<li><b>{_h(ref['id'])}</b>: {_h(ref['citation'])}, "
            f"{_h(ref['title'])}.{_h(note)}{_h(verify)}</li>"
        )
    body.append("</ul></section>")
    title = f"DPIA {run.repo}"
    return (
        '<!doctype html><html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        f"<title>{_h(title)}</title><style>{CSS}</style><script>{JS}</script></head>"
        f"<body><main>{''.join(body)}</main></body></html>\n"
    )


def citations_in(text: str) -> set[str]:
    return set(CITATION.findall(text))


def finding_anchor_ids(markup: str) -> set[str]:
    return {m.upper() for m in re.findall(r'id="(f-\d{4,})"', markup)}
